SINA_SMART["infect-rabies"] = {"lecture":"infect-rabies","title":"Rabies","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"infect-rabies:e0","text":"Rabies: viral zoonosis, always fatal once declared.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"infect-rabies:e1","text":"No curative treatment; prevention only.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"infect-rabies:e2","text":"Transmission by saliva: bites, scratches, licks on broken skin/mucosa.","topic":"Transmission and epidemiology","sec":1,"importance":"core","highYield":"untested"},{"id":"infect-rabies:e3","text":"Human-to-human: corneal transplant.","topic":"Transmission and epidemiology","sec":1,"importance":"core","highYield":"untested"},{"id":"infect-rabies:e4","text":"Morocco: dogs 89%, cats 5%; young, male, rural.","topic":"Transmission and epidemiology","sec":1,"importance":"core","highYield":"untested"},{"id":"infect-rabies:e5","text":"Virus travels along peripheral nerves to the CNS.","topic":"Pathophysiology","sec":2,"importance":"core","highYield":"untested"},{"id":"infect-rabies:e6","text":"Incubation 20-60 days (15 d-1 year); shorter in children and head bites.","topic":"Clinical course","sec":3,"importance":"core","highYield":"untested"},{"id":"infect-rabies:e7","text":"Prodrome: tingling at the bite site.","topic":"Clinical course","sec":3,"importance":"core","highYield":"untested"},{"id":"infect-rabies:e8","text":"Furious rabies: hydrophobia, aerophobia, agitation, clear consciousness.","topic":"Clinical course","sec":3,"importance":"core","highYield":"untested"},{"id":"infect-rabies:e9","text":"Death within 3-6 days.","topic":"Clinical course","sec":3,"importance":"core","highYield":"untested"},{"id":"infect-rabies:e10","text":"Post-exposure: wash the wound, vaccine ± immunoglobulins.","topic":"Prevention","sec":4,"importance":"core","highYield":"untested"},{"id":"infect-rabies:e11","text":"Observe the dog (virus shed ~3 days before signs).","topic":"Prevention","sec":4,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"nqikto":"a","ld0kou":"a","i2lswn":"a","1vh2b1t":"a","1hxeea4":"a","5ab0o6":"a","1ut40yi":"a","e6wfpg":"a","p6wowx":"a","bjt8l4":"a","115occ9":"a","nwv75c":"a","1u3mozt":"a","18h69h6":"a"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"infect-rabies:e0":{"s":0,"u":["Rabies: viral zoonosis, always fatal once declared.","Rabies is a viral zoonosis of domestic and wild animals causing an encephalomyelitis that is always fatal once symptoms appear."],"dp":[]},"infect-rabies:e1":{"s":0,"u":["No curative treatment; prevention only.","There is no curative treatment : only prevention works, made possible by the long incubation."],"dp":[]},"infect-rabies:e2":{"s":1,"u":["Transmission by saliva: bites, scratches, licks on broken skin/mucosa.","Spread by saliva : bites, scratches, licking of broken skin or mucous membranes.","Human-to-human transmission is known only through corneal transplants (and in theory bites, though human saliva is poorly virulent and no such case has been reported)."],"dp":[]},"infect-rabies:e3":{"s":1,"u":["Human-to-human: corneal transplant.","Human-to-human transmission is known only through corneal transplants (and in theory bites, though human saliva is poorly virulent and no such case has been reported)."],"dp":[]},"infect-rabies:e4":{"s":1,"u":["Morocco: dogs 89%, cats 5%; young, male, rural.","In Morocco : 54% under 20 years, 73% male, 79% rural; the biting animal is a dog in 89% and a cat in 5%."],"dp":[]},"infect-rabies:e5":{"s":2,"u":["Virus travels along peripheral nerves to the CNS.","The virus migrates along peripheral nerves to the spinal ganglion and then the CNS, where it prefers the rhinencephalon (making animals bite furiously), replicates, and spreads centrifugally along nerves to organs including the salivary glands ."],"dp":[{"h":"Why rabies can be prevented after the bite","t":"The virus travels slowly along nerves, taking weeks to reach the brain. A vaccine given right after exposure produces neutralising antibodies within that time, and immunoglobulins injected into the wound neutralise virus at the site immediately. Once the virus reaches the brain and symptoms appear, nothing stops it, which is why the response must be immediate. Source: the lecture's incubation and prophylaxis slides."}]},"infect-rabies:e6":{"s":3,"u":["Incubation 20-60 days (15 d-1 year); shorter in children and head bites.","Incubation : silent, 20-60 days on average (15 days to 1 year), shorter in children and with deep, multiple bites close to the nervous system."],"dp":[]},"infect-rabies:e7":{"s":3,"u":["Prodrome: tingling at the bite site.","Prodrome : tingling or itching at the bite (50-80%), myoclonus, anxiety, insomnia, logorrhoea, fever, digestive signs."],"dp":[]},"infect-rabies:e8":{"s":3,"u":["Furious rabies: hydrophobia, aerophobia, agitation, clear consciousness.","State phase : furious rabies (frequent): agitation, screaming, spitting, biting, hallucinations, skin and sensory hyperaesthesia, aerophobia and hydrophobia (unable to drink, agitation at the sight of water or a draught), dysautonomia (fever, sweating, irregular breathing), with normal consciousness ; or paralytic rabies (less frequent): ascending flaccid paralysis, bulbar involvement."],"dp":[]},"infect-rabies:e9":{"s":3,"u":["Death within 3-6 days.","Always fatal within 3-6 days from spasm or cardiorespiratory arrest.","Incubation : silent, 20-60 days on average (15 days to 1 year), shorter in children and with deep, multiple bites close to the nervous system."],"dp":[]},"infect-rabies:e10":{"s":4,"u":["Post-exposure: wash the wound, vaccine ± immunoglobulins.","After exposure : clean the wound immediately (the simplest and most useful act, even hours or days later); assess severity at an anti-rabies centre ; vaccination ± specific immunoglobulins (sero-vaccination)."],"dp":[{"h":"Why washing the wound matters so much","t":"Soap and water physically remove and inactivate much of the virus before it enters nerve endings. It costs nothing, needs no centre and remains useful even if the patient arrives hours or days later, which is why the lecture calls it the simplest and most useful act. Source: the lecture's measures in case of exposure slide."}]},"infect-rabies:e11":{"s":4,"u":["Observe the dog (virus shed ~3 days before signs).","Observe the biting animal : it can shed virus in saliva before signs appear (about 1 day for cats, 3 days (1-7) for dogs ); if it stays healthy, that is reassuring; if it falls ill, its brain is examined."],"dp":[]}},"meta":{"nqikto":{"a":"recall","vg":"infect-rabies:e0/recall/1"},"ld0kou":{"a":"recall","vg":"infect-rabies:e2/recall/1"},"i2lswn":{"a":"recall","vg":"infect-rabies:e3/recall/1"},"1vh2b1t":{"a":"recall","vg":"infect-rabies:e4/recall/1"},"1hxeea4":{"a":"recall","vg":"infect-rabies:e5/recall/1"},"5ab0o6":{"a":"recall","vg":"infect-rabies:e6/recall/1"},"1ut40yi":{"a":"recall","vg":"infect-rabies:e6/recall/2"},"e6wfpg":{"a":"recall","vg":"infect-rabies:e7/recall/1"},"p6wowx":{"a":"recall","vg":"infect-rabies:e8/recall/1"},"bjt8l4":{"a":"recall","vg":"infect-rabies:e8/recall/2"},"115occ9":{"a":"application","vg":"infect-rabies:e8/application/1"},"nwv75c":{"a":"recall","vg":"infect-rabies:e10/recall/1"},"1u3mozt":{"a":"relationship","vg":"infect-rabies:e10/relationship/1"},"18h69h6":{"a":"recall","vg":"infect-rabies:e11/recall/1"}},"explRev":"faabcd0dbd62"};
